import QtQuick
import Quickshell
import Quickshell.Io
import Quickshell.Wayland
import qs.services
import qs.modules.lock

ShellRoot {
    id: root

    readonly property string currentUser: Quickshell.env("USER") || Quickshell.env("LOGNAME") || ""

    /** Shared password state bridged between the auth input and the lock root. */
    property QtObject pw: QtObject {
        property string text: ""
    }

    /** Drives the pill-to-lock reveal. Kept off while the surface first mounts so the mask starts as the pill, then flipped on to grow it open; flipped back to collapse it before the session actually unlocks. */
    property bool revealed: false

    Auth {
        id: pamAuth
        user: root.currentUser
        onSucceeded: {
            root.revealed = false;
            collapse.restart();
        }
    }

    Timer {
        id: collapse
        interval: 640
        onTriggered: {
            sessionLock.locked = false;
            Cava.enabled = false;
            root.pw.text = "";
        }
    }

    /** Fires as soon as the event loop frees after the lock surfaces are built, which is the earliest the grow can start without the fresh output dropping its first frames. */
    Timer {
        id: reveal
        interval: 1
        onTriggered: root.revealed = true
    }

    function doLock(): void {
        root.pw.text = "";
        root.revealed = false;
        sessionLock.locked = true;
        Cava.enabled = true;
        reveal.restart();
    }

    /**
     * Fast lock trigger. Spawning a fresh `qs ipc call` client to ask for the lock
     * cost a quarter second of Qt startup on the critical path; instead lock.sh just
     * touches this file and the watch fires the lock, shaving that off the delay.
     * The IPC handler stays as a fallback for any other caller.
     *
     * An external write lands as a burst of change events, so the fire is debounced
     * into one; primed gates out the startup events (including the file's own
     * creation) so the daemon never locks itself on launch.
     */
    property bool triggerPrimed: false
    Timer {
        interval: 800
        running: true
        onTriggered: root.triggerPrimed = true
    }
    Timer {
        id: triggerFire
        interval: 60
        onTriggered: if (root.triggerPrimed)
            root.doLock()
    }
    FileView {
        path: (Quickshell.env("XDG_RUNTIME_DIR") || "/tmp") + "/ricelin-lock-trigger"
        watchChanges: true
        printErrors: false
        onLoadFailed: setText("0")
        onFileChanged: triggerFire.restart()
    }



    WlSessionLock {
        id: sessionLock
        locked: false

        WlSessionLockSurface {
            id: lockSurface
            color: "#160f0a"

            LockSurface {
                anchors.fill: parent
                s: lockSurface.screen ? lockSurface.screen.height / 1080 : 1
                screenName: lockSurface.screen ? lockSurface.screen.name : ""
                auth: pamAuth
                pw: root.pw
                active: root.revealed
            }
        }
    }

}

import QtQuick
import Quickshell
import Quickshell.Io
import Quickshell.Wayland
import qs.services
import qs.modules.launcher
import "../../utils/fuzzy.js" as Fuzzy

ShellRoot {
    id: root

    property string query: ""
    property var usage: ({})
    property bool shown: false
    property string targetMonitor: ""

    FileView {
        id: usageStore
        path: (Quickshell.env("XDG_STATE_HOME") || (Quickshell.env("HOME") + "/.local/state")) + "/ricelin/launcher-usage.json"
        blockLoading: true
        atomicWrites: true
        printErrors: false
    }

    Component.onCompleted: {
        var raw = usageStore.text();
        try {
            root.usage = raw && raw.length ? JSON.parse(raw) : ({});
        } catch (e) {
            root.usage = ({});
        }
    }

    readonly property var allEntries: {
        var src = DesktopEntries.applications.values;
        var out = [];
        for (var i = 0; i < src.length; i++)
            if (src[i] && !src[i].noDisplay) out.push(src[i]);
        return out;
    }

    readonly property int totalCount: allEntries.length
    readonly property var results: Fuzzy.rank(allEntries, query, usage)

    function run(entry) {
        if (entry) {
            if (entry.id) {
                root.usage[entry.id] = (root.usage[entry.id] || 0) + 1;
                usageStore.setText(JSON.stringify(root.usage));
                usageStore.waitForJob();
            }
            entry.execute();
        }
        root.shown = false;
    }

    Variants {
        model: Quickshell.screens

        PanelWindow {
            id: win
            required property var modelData
            screen: modelData
            visible: root.shown && root.targetMonitor === modelData.name

            color: "transparent"
            exclusionMode: ExclusionMode.Ignore
            WlrLayershell.layer: WlrLayer.Overlay
            WlrLayershell.keyboardFocus: WlrKeyboardFocus.Exclusive
            WlrLayershell.namespace: "launcher"

            anchors { top: true; left: true; right: true; bottom: true }

            MouseArea {
                anchors.fill: parent
                onClicked: root.shown = false
            }

            Launcher {
                id: launcher
                anchors.centerIn: parent

                entries: root.results
                total: root.totalCount

                onLaunch: (entry) => root.run(entry)
                onQuit: root.shown = false
            }

            Connections {
                target: launcher
                function onQueryChanged() {
                    root.query = launcher.query;
                    launcher.selectedIndex = 0;
                }
            }

            onVisibleChanged: {
                if (visible) {
                    launcher.query = "";
                    launcher.selectedIndex = 0;
                    launcher.focusField();
                }
            }
        }
    }
}

import QtQuick
import Quickshell
import Quickshell.Io
import Quickshell.Hyprland

import qs.services
import qs.modules.pill
import qs.modules.lock
import qs.modules.screencorner
import qs.modules.launcher

ShellRoot {
    id: shell

    PillRoot {
        id: pillRoot
    }

    LockRoot {
        id: lockRoot
    }

    ScreenCornerRoot {
        id: cornerRoot
    }

    LauncherRoot {
        id: launcherRoot
    }

    IpcHandler {
        target: "pill"
        function mixer(mon: string): void { pillRoot.toggleSurface(mon, "mixer"); }
        function calendar(mon: string): void { pillRoot.toggleSurface(mon, "calendar"); }
        function launcher(mon: string): void { pillRoot.toggleSurface(mon, "launcher"); }
        function power(mon: string): void { pillRoot.toggleSurface(mon, "power"); }
        function link(mon: string): void { pillRoot.toggleSurface(mon, "link"); }
        function battery(mon: string): void { pillRoot.toggleSurface(mon, "battery"); }
        function settings(mon: string): void { pillRoot.toggleSurface(mon, "settings"); }
        function keybinds(mon: string): void { pillRoot.toggleSurface(mon, "keybinds"); }
        function recorder(mon: string): void { pillRoot.toggleSurface(mon, "recorder"); }
        function screenrec(mon: string): void { pillRoot.toggleSurface(mon, "recorder"); }
        function record(mon: string): void { pillRoot.toggleSurface(mon, "recorder"); }
        function quickRecord(mon: string): void {
            if (ScreenRec.recording) {
                ScreenRec.stop();
            } else if (ScreenRec.counting) {
                ScreenRec.cancel();
            } else if (ScreenRec.quickChoosing) {
                ScreenRec.quickChoosing = false;
                ScreenRec.quickScreenChoosing = false;
            } else {
                ScreenRec.quickMon = mon;
                ScreenRec.quickScreenChoosing = false;
                ScreenRec.quickChoosing = true;
            }
        }
        function gameMode(mon: string): void { Flags.gameMode = !Flags.gameMode; }
        function sysmon(mon: string): void { pillRoot.toggleSurface(mon, "sysmon"); }
        function system(mon: string): void { pillRoot.toggleSurface(mon, "sysmon"); }
        function clipboard(mon: string): void { pillRoot.toggleSurface(mon, "clipboard"); }
        function wallpaper(mon: string): void { pillRoot.toggleSurface(mon, "wallpaper"); }
        function media(mon: string): void {
            if (Players.list.length > 0)
                pillRoot.toggleSurface(mon, "media");
        }
        function peek(mon: string): void { pillRoot.peek(mon); }
        function hide(): void { pillRoot.close(); }
        function page(mon: string, name: string): void { pillRoot.toggleSurface(mon, name); }
        function minimizeWindow(addr: string): void {
            Hyprland.dispatch('hl.dsp.window.move({ workspace = "special:minimized", follow = false, window = "address:' + addr + '" })');
        }
        function restoreWindow(arg: string): void {
            var p = arg.split("|");
            if (p.length < 2 || p[0].length === 0)
                return;
            Hyprland.dispatch('hl.dsp.window.move({ workspace = ' + p[1] + ', window = "address:' + p[0] + '" })');
        }
    }

    IpcHandler {
        target: "lock"
        function lock(): void { lockRoot.doLock(); }
    }

    IpcHandler {
        target: "launcher"
        function show(mon: string): void { launcherRoot.targetMonitor = mon; launcherRoot.shown = true; }
        function hide(): void { launcherRoot.shown = false; }
        function toggle(mon: string): void {
            if (launcherRoot.shown) { launcherRoot.shown = false; return; }
            launcherRoot.targetMonitor = mon;
            launcherRoot.shown = true;
        }
    }
}

